&lt;p&gt;&lt;span style="font-size:12px"&gt;&lt;strong&gt;Deceased:&amp;nbsp;&lt;/strong&gt;&lt;span style="font-family:segoe ui,segoe ui_embeddedfont,segoe ui_msfontservice,sans-serif"&gt;Melinda&amp;nbsp;Ann&amp;nbsp;Lyons,&amp;nbsp;85-year-old Bend resident&lt;/span&gt;&lt;span style="font-family:segoe ui,segoe ui_embeddedfont,segoe ui_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
